// ============================================
// VALIDATION INPUT
// ============================================

const input = $input.first().json;
const body = input.body || {};
const headers = input.headers || {};

// --- Extraction Project ID ---
const projectId = headers['x-project-id'] 
  || headers['X-Project-ID'] 
  || headers['X-Project-Id']
  || 'unknown';

// --- Validation discord_user_id ---
if (!body.discord_user_id) {
  return {
    error: true,
    error_code: 'MISSING_USER_ID',
    message: 'Le champ "discord_user_id" est requis'
  };
}

// --- Validation item_ids ---
if (!body.item_ids || !Array.isArray(body.item_ids) || body.item_ids.length === 0) {
  return {
    error: true,
    error_code: 'MISSING_ITEM_IDS',
    message: 'Le champ "item_ids" est requis et doit etre un tableau non vide'
  };
}

// --- Retour des donnees validees ---
return {
  error: false,
  data: {
    discord_user_id: body.discord_user_id,
    item_ids: body.item_ids,
    project_id: projectId
  }
};

// ============================================
// FORMAT SUCCESS RESPONSE
// ============================================

const apiResponse = $input.first().json;
const validationData = $('Validate Input').first().json;

// --- Check API errors ---
if (apiResponse.error || apiResponse.success === false) {
  return {
    success: false,
    error: {
      code: apiResponse.error?.code || 'API_ERROR',
      message: apiResponse.error?.message || 'Erreur API',
      http_status: apiResponse.error?.http_status || 500
    }
  };
}

// --- Format total_display ---
const cart = apiResponse.cart || apiResponse;
const totalEuros = (cart.total_cents || 0) / 100;
const totalDisplay = totalEuros.toLocaleString('fr-FR', {
  minimumFractionDigits: 2,
  maximumFractionDigits: 2
}) + ' EUR';

return {
  success: true,
  removed_count: validationData.data.item_ids.length,
  cart: {
    id: cart.id,
    items: cart.items || [],
    subtotal_cents: cart.subtotal_cents || 0,
    discount_cents: cart.discount_cents || 0,
    total_cents: cart.total_cents || 0,
    total_display: totalDisplay,
    item_count: cart.item_count || (cart.items?.length || 0),
    currency: cart.currency || 'EUR'
  }
};

// ============================================
// FORMAT ERROR RESPONSE (Validation)
// ============================================

const input = $input.first().json;

return {
  success: false,
  error: {
    code: input.error_code || 'VALIDATION_ERROR',
    message: input.message || 'Erreur de validation',
    http_status: 400
  }
};

